"""Netact alarms"""
from __future__ import print_function
from taf.ul.trs_e2e_fw.lib.ems.exceptions import AlarmParameterNotFoundException, \
    DuplicateAlarmValueException, NoAlarmValueException, AlarmIdOrFaultIdOnlyException
from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase
from taf.ul.trs_e2e_fw.lib.utils.verification.alarms import AlarmsVerification
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable

logger = BackgroundLogger.Instance()


class Alarms(NetactBase):
    """Netact alarms"""
    def __init__(self):
        super(Alarms, self).__init__()
        self.default_distname = "PLMN-PLMN/MRBTS-{}".format(get_config_variable(['bts_id']))

    def verify_alarm(self, **kwargs):
        """Verify alarm"""
        fault_id = kwargs.get("faultid", None)
        # if fault id is not present accept alarm id
        alarm_id = kwargs.get("alarmid", None)

        # either faultid or alarmid must be passed:
        if (fault_id and alarm_id) or (not fault_id and not alarm_id):
            raise AlarmIdOrFaultIdOnlyException("Either alarmid or faultid should be passed, not both.")

        # severity = kwargs.get("severity", None)
        should_exist = bool(kwargs.get("should_exist", True))
        occurrences = int(kwargs.get("occurrences", 1))
        alias = kwargs.get('alias', "default")
        dist_name = kwargs.get('dist_name', self.default_distname)

        check_unexpected_alarms = kwargs.get("check_unexpected_alarms", False)
        expected_alarms = kwargs.get("expected_alarms", [])
        prev_alarms = kwargs.get("prev_alarms", None)
        interface = 'netact'
        logger.debug("Dist name:{}".format(dist_name))
        # alarms_list = self.netact_factory.monitor_fm.get_alarms(dist_name, alias=alias)
        alarms_list = self.netact_factory.netact.get_alarms(dist_name, alias=alias)
        logger.debug("#### alarms_list {}".format(alarms_list))
        alarms_list = self.convert_alarm_format(alarms_list, interface)
        AlarmsVerification().write_alarms_to_file('netact_alarms.json', alarms_list)
        # self._verify_alarm_exists(alarms_list, faultid, occurrences, should_exist)
        AlarmsVerification().verify_alarm_exists_and_validate_with_rise(alarms_list,
                                                                        check_unexpected_alarms,
                                                                        prev_alarms,
                                                                        expected_alarms,
                                                                        fault_id,
                                                                        occurrences,
                                                                        should_exist,
                                                                        alias, interface, alarm_id)
        return alarms_list

    def upload_alarms(self, **kwargs):
        """Upload alarms"""
        # timeout = kwargs.get('timeout', 1000)
        alias = kwargs.get('alias', "default")
        # return self.netact_factory.monitor_fm.upload_alarms(dist_name=self.default_distname,
        # timeout=timeout,
        # alias=alias)
        return self.netact_factory.netact.upload_alarms(dist_name=self.default_distname, alias=alias)

    def convert_alarm_format(self, alarms_netact_format, interface):
        """Convert alarm format"""
        alarms_general_format = []
        for alarm_details in alarms_netact_format:
            logger.debug("#### alarm_details is {}".format(alarm_details))
            alarm_dictionary = {}
            alarm_dictionary['#'] = alarms_netact_format.index(alarm_details) + 1
            try:
                alarm_dictionary['OBJECT'] = alarm_details['dn']
                alarm_dictionary['SEVERITY'] = alarm_details['perceivedSeverity']
                alarm_dictionary['TEXT'] = alarm_details['alarmText']
                alarm_dictionary['ALARM ID'] = alarm_details['specificProblem']
                alarm_dictionary['FAULT NAME'] = alarm_details['additionalText1']
                alarm_dictionary['SUPPL ALARM INFO'] = self._parse_additionalText3_param_from_fetched_alarm(
                    'supplAlarmInfo', alarm_details['additionalText3'])
                # alarm_dictionary['ACTIVITY'] = alarm_details[] #TBD if needed
                alarm_dictionary['TIME'] = AlarmsVerification().convert_date_format(alarm_details['alarmTime'],
                                                                                    interface)
                alarm_dictionary['FAULT ID'] = self._parse_additionalText3_param_from_fetched_alarm(
                    'additionalFaultID', alarm_details['additionalText3'])
                alarm_dictionary['srcIPAddr'] = self._parse_additionalText3_param_from_fetched_alarm(
                    'srcIPAddr', alarm_details['additionalText3'])
                alarm_dictionary['dstIPAddr'] = self._parse_additionalText3_param_from_fetched_alarm(
                    'dstIPAddr', alarm_details['additionalText3'])
            except KeyError as keyError:
                raise AlarmParameterNotFoundException("alarm parameter {} not found".format(
                    keyError))
            except AlarmParameterNotFoundException as e:
                raise AlarmParameterNotFoundException("alarm parameter {} not found".format(e))
            # alarm_dictionary['HEXID'] = alarm_details #TBD if needed
            alarms_general_format.append(alarm_dictionary)
        logger.debug("Converted format:{}".format(alarms_general_format))
        return alarms_general_format

    def _parse_additionalText3_param_from_fetched_alarm(self, parameter_name, additional_text3):
        fetched_fault_id = None
        if additional_text3 is not None and parameter_name in additional_text3:
            if parameter_name == 'additionalFaultID':
                fetched_fault_id = additional_text3.split(parameter_name)[1].replace('=', '').split(" ")[0] if len(
                    additional_text3.split(parameter_name)) > 1 else None
                if fetched_fault_id != 'None':
                    return fetched_fault_id
            else:
                return self._remove_additional_text(parameter_name=parameter_name,
                                                    fetched_additionalInfo3=additional_text3)
        if parameter_name == 'additionalFaultID' and fetched_fault_id is not None:
            raise AlarmParameterNotFoundException("{} is not found".format(parameter_name))

    def _remove_additional_text(self, parameter_name, fetched_additionalInfo3):
        key_attr = ['additionalFaultID', 'supplAlarmInfo', 'srcIPAddr', 'dstIPAddr', 'additionalFaultReason']
        for i in key_attr:
            if i.lower() != parameter_name.lower():
                return fetched_additionalInfo3.replace(i, '')

    def configure_maintenance_mode(self, **kwargs):
        """
         Uses the mamo operation of the fmCLI.sh script to set or resume maintenance mode.

        Parameters:
        operation: Value can be either 'set' or 'resume'
        dist_name (string):
        comment (string): Mandatory, In case operation selected is 'set'
        alias (string): Name of execution context.

        Returns:
            command output

        Return type:
            string

        """
        operation = kwargs["operation"]

        logger.debug("Performing operation {}...".format(operation.upper().replace("_", " ")))
        try:
            return getattr(self, "_{}_maintenance_mode".format(operation.lower()))(**kwargs)
        except AttributeError:
            raise Exception("Operation {} not supported".format(operation))

    def _set_maintenance_mode(self, **kwargs):
        """
        Uses the mamo operation of the fmCLI.sh script to set maintenance mode.

        Parameters:
        dist_name (string):
        comment (string):
        alias (string): Name of execution context.

        Returns:
        command output

        Return type:
        string
        """
        dist_name = kwargs["dist_name"]
        comment = kwargs["comment"]
        alias = kwargs.pop("alias", "default")
        include_subtree = kwargs.pop("include_subtree", False)
        # return self.netact_factory.monitor_fm.set_maintenance_mode(dist_name=dist_name, comment=comment, alias=alias)
        return self.netact_factory.netact.set_maintenance_mode(dist_name=dist_name, include_subtree=include_subtree,
                                                               comment=comment, alias=alias)

    def _resume_maintenance_mode(self, **kwargs):
        """
        Uses the mamo operation of the fmCLI.sh script to resume maintenance mode.

        Parameters:
        dist_name (string):
        alias (string): Name of execution context.

        Returns:
        command output

        Return type:
        string

        """
        dist_name = kwargs["dist_name"]
        alias = kwargs.pop("alias", "default")
        include_subtree = kwargs.pop("include_subtree", False)
        # return self.netact_factory.monitor_fm.resume_maintenance_mode(dist_name=dist_name, alias=alias)
        return self.netact_factory.netact.resume_maintenance_mode(dist_name=dist_name,
                                                                  include_subtree=include_subtree, alias=alias)

    def cancel_alarms(self, **kwargs):
        """
        This keyword uses the bulkcancelalarms operation of the fmCLI.sh script to cancel alarms. The Monitor FM
        features are based on official fmCLI.sh CLI, internal REST API and internal neIntegration.zip CLI.

        Parameters:
        dist_name (string)
        alarm_number ((string|int)) - The maximum number of parallel alarm cancel operations supported is 10. When
            alarm cancel operations are initiated beyond the maximum number, the operation fails with a message.
        alarm_file (string) - If alarm_file is given absolute path of the alarm file must be provided
        include_subnetworks (bool) - Specifies if child managed objects of distinguished name must be considered
            while performing alarm cancel operation. The default value set is false
        alias (string) - Name of execution context.

        Returns:
        Command output

        Return type:
        String
        """
        dist_name = kwargs['dist_name']
        alarm_number = kwargs.pop('alarm_number', None)
        alarm_file = kwargs.pop('alarm_file', None)
        if alarm_file is not None and alarm_number is not None:
            raise DuplicateAlarmValueException("Please pass a value for either alarm_file or alarm_number, not both.")
        if alarm_number is None and alarm_file is None:
            raise NoAlarmValueException("Please pass a value for either alarm_file or alarm_number. None passed")
        include_subnetworks = kwargs.pop('include_subnetworks', False)
        alias = kwargs.pop('alias', 'default')

        return self.netact_factory.netact.cancel_alarms(dist_name, alarm_number=alarm_number, alarm_file=alarm_file,
                                                        include_subnetworks=include_subnetworks, alias=alias)
